using System;using System.IO;using System.Linq;using System.Threading;using System.Threading.Tasks;using UnityEngine;
public static class BeeQueenLimitTests {
 static void Check(bool b,string label){if(!b)throw new Exception(label);}
 static GameWorld World(){var w=new GameWorld(new WeatherSimulator(WeatherSimulator.DefaultSeed,WeatherAssetLoader.LoadBaseline(),null,123456789UL));w.BeeCycle.SeedDemo();return w;}
 static void Case(bool queen,double development,double health,bool dead){var w=World();try{var b=w.BeeCycle.Bees.First(x=>x.stage==CycleStage.Adult&&x.queen==queen);b.development=development;b.health=health;GameTimeRuntime.CreateWorldScheduler(w).RunToAsync(w.CurrentGameMinute+1,()=>Task.CompletedTask,()=>Task.CompletedTask,CancellationToken.None).GetAwaiter().GetResult();Check((b.stage==CycleStage.Dead)==dead,$"queen={queen} development={development} health={health}");}finally{w.Thermal.Dispose();}}
 public static void Run(){
 Check(Resources.Load<BeeCycleSettingsAsset>("BeeCycleParameters").values.queenMaxDevelopment==1500,"asset default");Check(new BeeCycleSettings().queenMaxDevelopment==1500,"code default");
 Case(true,200,100,false);Case(true,1499,100,false);Case(true,1500,100,true);Case(true,1499.999999,100,true);Case(false,199,100,false);Case(false,200,100,true);Case(false,199.999999,100,true);Case(true,100,0,true);
 var w=World();try{var cfg=w.BeeCycle.Settings;cfg.queenMaxDevelopment=1700;w.BeeCycle.ApplySettings(cfg);var snap=new WorldSaveSnapshot{World=w,UtcTicks=1,TargetMinute=w.CurrentGameMinute};var bytes=WorldSaveCodec.Encode(snap);Check(bytes.SequenceEqual(WorldSaveCodec.EncodeAsync(snap,()=>Task.CompletedTask).GetAwaiter().GetResult()),"async bytes");foreach(var data in new[]{bytes,WorldSaveCodec.EncodeLegacy(snap)}){WorldSaveCodec.Validate(data);var restored=WorldSaveCodec.Decode(data).World;try{Check(restored.BeeCycle.Settings.queenMaxDevelopment==1700&&restored.BeeCycle.Settings.maxDevelopment==200,"persist independent limits");}finally{restored.Thermal?.Dispose();}}}finally{w.Thermal.Dispose();}
 var root=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../bee-annual-20261124/day0.bytes"));var old=WorldSaveCodec.Decode(File.ReadAllBytes(root)).World;try{Check(old.BeeCycle.Settings.queenMaxDevelopment==1500&&old.BeeCycle.Bees.Count==109,"schema24 new field default and population preserved");Check(old.BeeCycle.Settings.commandMaximum==0.003&&old.BeeCycle.Settings.maxDevelopment==200,"old settings preserved");}finally{old.Thermal?.Dispose();}
 var bad=new BeeCycleSettings{queenMaxDevelopment=21};bool rejected=false;try{bad.Validate();}catch(ArgumentException){rejected=true;}Check(rejected,"invalid queen limit rejected");Debug.Log("QUEEN LIMIT PASS: 8 tick boundary cases, health death, custom compact/reflected/async roundtrip, schema24 migration, parameter validation");
 }
}